/* Generated item art and solid landscape obstacles. */
(()=>{'use strict';const T=THREE,W=EmberTerrain,P=EmberWorld.prototype,card=new T.PlaneGeometry(1,1),shadowGeo=new T.CircleGeometry(.45,24),shadowMat=new T.MeshBasicMaterial({color:'#10231c',transparent:true,opacity:.19,depthWrite:false,side:T.DoubleSide});
P.itemVisual=function(id,held=false){const art=SurvivalItemArt[id];if(!art)throw Error('No generated artwork for '+id);this.itemMaterials ||= new Map();let entry=this.itemMaterials.get(id);if(!entry){const texture=this.loader.load(art.src);texture.encoding=T.sRGBEncoding;texture.anisotropy=4;const [x,y,w,h]=art.uv;texture.offset.set(x,y);texture.repeat.set(w,h);entry={texture,sprite:new T.SpriteMaterial({map:texture,transparent:true,alphaTest:.08,depthWrite:false,toneMapped:false}),held:new T.MeshBasicMaterial({map:texture,transparent:true,alphaTest:.08,depthWrite:false,toneMapped:false,side:T.DoubleSide})};this.itemMaterials.set(id,entry);}const ratio=art.width/art.height,g=new T.Group(),size=held?.9:({wood:.8,stone:.55,fiber:.55,ore:.5,crystal:.7,resin:.35,berry:.35,fuel:.6,arrow:.85,sword:1.15,spear:1.4,axe:1.05,bow:1.05,house:.85,campfire:.65,chest:.65}[id]||.7),width=ratio>=1?size:size*ratio,height=ratio>=1?size/ratio:size;let image;if(held){image=new T.Mesh(card,entry.held);image.position.y=height*.22;}else{image=new T.Sprite(entry.sprite);image.center.set(.5,0);const shadow=new T.Mesh(shadowGeo,shadowMat);shadow.rotation.x=-Math.PI/2;shadow.position.y=.018;shadow.scale.set(width,width,1);g.add(shadow);}image.scale.set(width,height,1);image.userData.artId=id;g.userData.artId=id;g.add(image);return g;};
P.lootVisual=function(point,items,state){const g=this.group(point.x,point.y,point.z,this.dynamic),entries=Object.entries(items).filter(([,count])=>count>0),columns=Math.min(4,Math.ceil(Math.sqrt(entries.length)));entries.forEach(([id,count],n)=>{const art=this.itemVisual(id),x=(n%columns-(columns-1)/2)*.8,z=(Math.floor(n/columns)-Math.floor((entries.length-1)/columns)/2)*.7;art.position.set(x,this.floor(point.x+x,point.z+z,point.y,state||{structures:[]})-point.y+.025,z);const shadow=art.children.find(o=>o.isMesh);if(shadow){const wx=point.x+x,wz=point.z+z,n=new T.Vector3(W.ground(wx-.1,wz)-W.ground(wx+.1,wz),.2,W.ground(wx,wz-.1)-W.ground(wx,wz+.1)).normalize();shadow.quaternion.setFromUnitVectors(new T.Vector3(0,0,1),n);}art.userData.count=count;g.add(art);});g.userData.itemIds=entries.map(([id])=>id);return g;};
P.nearbyRocks=function(x,z){const out=[],wx=x+W.anchor.x,wz=z+W.anchor.z,add=r=>{const b=r.bounds;if(b&&wx>b.min.x-.4&&wx<b.max.x+.4&&wz>b.min.z-.4&&wz<b.max.z+.4)out.push(r);};for(const chunk of this.native.chunks.values()){if(chunk.userData.distant)continue;if(Math.abs(chunk.userData.east+64-wx)>74||Math.abs(chunk.userData.north+64-wz)>74)continue;for(const r of chunk.userData.rocks||[])add(r);}for(const r of this.entranceRocks||[])add(r);return out;};
const rockTop=(r,x,z,padding=0)=>{let top=NaturalRocks.topAt(r,x+W.anchor.x,z+W.anchor.z);if(padding)for(let n=0;n<8;n++){const a=n*Math.PI/4,h=NaturalRocks.topAt(r,x+W.anchor.x+Math.cos(a)*padding,z+W.anchor.z+Math.sin(a)*padding);if(h!==null)top=top===null?h:Math.max(top,h);}return top===null?null:top-W.anchor.y;};
const ellipseTop=(r,x,z,padding=0)=>{const d=((x-r.x)/(r.sx+padding))**2+((z-r.z)/(r.sz+padding))**2;return d<=1?r.y+r.sy*Math.sqrt(1-d):null;};
const oldFloor=P.floor,oldBlocked=P.blocked;
P.floor=function(x,z,y,state){let h=oldFloor.call(this,x,z,y,state);for(const r of this.nearbyRocks(x,z)){const top=rockTop(r,x,z);if(top!==null&&y>=top-.32)h=Math.max(h,top);}if(!W.bossContentEnabled)return h;const s=W.shrine,dist=Math.hypot(x-s.x,z-s.z);if(W.onIsland(x,z,{x:s.x,z:s.z,r:7})&&y>=s.y-.2)h=Math.max(h,s.y+.15);if(dist<3&&y>=s.y+.48)h=Math.max(h,s.y+.8);for(let n=0;n<5;n++){const a=n/5*Math.PI*2;if(Math.hypot(x-s.x-Math.sin(a)*4,z-s.z-Math.cos(a)*4)<.6&&y>=s.y+1.28)h=Math.max(h,s.y+1.6);}if(this.shrineRamp){const r=this.shrineRamp;if(Math.abs(x-r.x)<r.width/2&&z>=r.z&&z<=r.z+r.length)h=Math.max(h,T.MathUtils.lerp(r.top,r.bottom,(z-r.z)/r.length));}return h;};
P.blocked=function(x,z,y,state){if(oldBlocked.call(this,x,z,y,state)||W.caveBlocked(x,z,y))return true;for(const r of this.nearbyRocks(x,z)){const top=rockTop(r,x,z,.3);if(top!==null&&y<top-.32&&y+1.7>r.bounds.min.y-W.anchor.y)return true;}if(!W.bossContentEnabled)return false;const s=W.shrine,dx=x-s.x,dz=z-s.z,dist=Math.hypot(dx,dz);if(dist<7.3&&y<s.y-.2&&!this.onShrineRamp(x,z))return true;if(dist<3.32&&y<s.y+.48&&y+1.7>s.y+.01)return true;const gemTop=ellipseTop({x:s.x,z:s.z,y:s.y+1.8,sx:.7,sz:.7,sy:1.2},x,z,.3);if(gemTop!==null&&y<gemTop-.2&&y+1.7>s.y+.6)return true;for(let n=0;n<5;n++){const a=n/5*Math.PI*2;const px=s.x+Math.sin(a)*4,pz=s.z+Math.cos(a)*4;if(Math.hypot(x-px,z-pz)<.9&&y<s.y+1.28&&y+1.7>s.y)return true;const socketTop=ellipseTop({x:px,z:pz,y:s.y+1.9,sx:.42,sz:.42,sy:.65},x,z,.3);if(socketTop!==null&&y<socketTop-.15&&y+1.7>s.y+1.25)return true;}return false;};
P.onShrineRamp=function(x,z){const r=this.shrineRamp;return r&&Math.abs(x-r.x)<=r.width/2+.35&&z>=r.z-.35&&z<=r.z+r.length+.35;};
P.buildShrineApproach=function(){const s=W.shrine,top=s.y+.15,z=s.z+6.8,length=Math.max(7,(top-W.ground(s.x,z+10))/.5),bottom=W.ground(s.x,z+length);this.shrineRamp={x:s.x,z,width:3.2,length,top,bottom};const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute([s.x-1.6,top,z,s.x-1.6,bottom,z+length,s.x+1.6,bottom,z+length,s.x+1.6,top,z],3));geo.setAttribute('uv',new T.Float32BufferAttribute([0,0,0,3,1,3,1,0],2));geo.setIndex([0,1,2,0,2,3]);geo.computeVertexNormals();const m=new T.Mesh(geo,this.mat('#8e9c99',false,'moss-stone'));m.receiveShadow=true;this.static.add(m);};
})();
